#!/usr/bin/env ruby
# frozen_string_literal: true

# Generate Formula/puck.rb from a release SHA256SUMS file.
# Usage: generate-formula.rb <version> <SHA256SUMS> [out]

version = ARGV.fetch(0)
sums_path = ARGV.fetch(1)
out_path = ARGV.fetch(2, "Formula/puck.rb")

sums = {}
File.readlines(sums_path).each do |line|
  sha, name = line.strip.split(/\s+/, 2)
  next if name.nil? || name.empty?
  sums[name] = sha
end

def need(sums, name)
  sums.fetch(name) { raise "missing #{name} in SHA256SUMS" }
end

arm_mac = need(sums, "puck-aarch64-apple-darwin.tar.gz")
intel_mac = need(sums, "puck-x86_64-apple-darwin.tar.gz")
arm_linux = need(sums, "puck-aarch64-unknown-linux-musl.tar.gz")
intel_linux = need(sums, "puck-x86_64-unknown-linux-musl.tar.gz")
base = "https://github.com/VerburgtJimmy/puck/releases/download/v#{version}"

File.write(out_path, <<~RUBY)
  # frozen_string_literal: true

  # Generated by dist/homebrew/generate-formula.rb — do not edit by hand.
  # brew tap VerburgtJimmy/puck https://github.com/VerburgtJimmy/puck
  # brew install puck

  class Puck < Formula
    desc "Native PHP package installer (Composer-compatible vendor/)"
    homepage "https://github.com/VerburgtJimmy/puck"
    version "#{version}"
    license "MIT"

    on_macos do
      on_arm do
        url "#{base}/puck-aarch64-apple-darwin.tar.gz"
        sha256 "#{arm_mac}"
      end
      on_intel do
        url "#{base}/puck-x86_64-apple-darwin.tar.gz"
        sha256 "#{intel_mac}"
      end
    end

    on_linux do
      on_arm do
        url "#{base}/puck-aarch64-unknown-linux-musl.tar.gz"
        sha256 "#{arm_linux}"
      end
      on_intel do
        url "#{base}/puck-x86_64-unknown-linux-musl.tar.gz"
        sha256 "#{intel_linux}"
      end
    end

    def install
      bin.install "puck"
    end

    test do
      assert_match(/puck/, shell_output("\#{bin}/puck --help"))
    end
  end
RUBY

warn "wrote #{out_path} for v#{version}"
